"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["20751"],{76415(e){e.exports=JSON.parse('{"id":"FIN-788","slug":"government-debt","term":"Government Debt","also_known_as":[],"difficulty":"Intermediate","definition":"Government debt is the total amount of money a government owes to its creditors, accumulated from past budget deficits.","explanation":["Governments borrow by issuing bonds and other securities, which are bought by domestic and foreign investors, banks, pension funds, insurance companies and central banks. Government debt is also called public debt, national debt or sovereign debt.","Debt builds up over time. Each year\'s budget deficit adds to the total, while a surplus can reduce it. For example, a government that runs a deficit of 50 billion every year for ten years will add around 500 billion to its debt, plus the interest owed.","Government debt allows governments to fund spending without immediately raising taxes, smooth out the effects of recessions and invest in long-term projects. Governments that borrow in their own currency and have strong institutions can often sustain high levels of debt.","High debt has potential drawbacks. Interest payments take up a growing share of the budget, leaving less for other spending. If investors lose confidence, borrowing costs can rise sharply, leading to a debt crisis. Debt levels are usually assessed relative to the size of the economy, using the debt-to-GDP ratio."],"note":"","total":1500,"prev":{"slug":"government-bond","term":"Government Bond"},"next":{"slug":"government-grant","term":"Government Grant"}}')}}]);